Oh, I guess I did not explain myself properly, adding "max" option to keep-alive header is only one part (which is not actually required for this feature)

My suggestion is to "cut" the connection when it reached the maximum number of requests,


for example

```javascript
const fp = require('fastify-plugin')
module.exports = fp(function (fastify, options, next) {
    let counter = {}
    fastify.addHook('onRequest', async (request, reply) => {
        if(counter[request.socket] === undefined){
            counter[request.socket]= 1
            return
        }else{
            counter[request.socket]++
        }
        if(counter[request.socket] >= 2){
            reply.header("connection", "close")
            delete counter[request.socket]
            // somewhere also request.socket.destroy() should be called
        }

    })
})
```

